"""Stage tiles for the Tour select screen (WP tour-select-screen-redesign). Original art generated by this script from the repo's own
grim floors (public/assets/img/floor/*.png, public/assets/img/background/void.png); no legacy pixels beyond those.
Run: python3 tools/assets/tour-gen/tour-tiles.py public/assets/img/tour     (needs numpy + Pillow; fixed seed, so byte-identical)
Writes <element>.webp for fire, water, earth, air and void: 480 x 270, dark, desaturated, grainy, with a soft horizon glow, a
painted silhouette ridge per element (fire: jagged spires, water: low swells, earth: broad crags, air: drifting ledges, void: a
broken rift ring) and a heavy vignette. The screen draws its own frame, stamp and text over them (assets/css/tour-select.css).
"""
import os
import sys
import numpy as np
from PIL import Image, ImageDraw, ImageFilter

W, H = 480, 270
SRC = {'fire': 'floor/fire.png', 'water': 'floor/water.png', 'earth': 'floor/earth.png', 'air': 'floor/air.png', 'void': 'background/void.png'}
STYLE = {
    'fire': dict(glow=(150, 64, 30), ridge=(14, 9, 9), keep=0.55),
    'water': dict(glow=(50, 92, 110), ridge=(8, 14, 18), keep=0.5),
    'earth': dict(glow=(120, 96, 58), ridge=(14, 11, 8), keep=0.5),
    'air': dict(glow=(110, 128, 150), ridge=(18, 22, 28), keep=0.45),
    'void': dict(glow=(96, 60, 120), ridge=(6, 4, 10), keep=0.35),
}


def ridge(kind, rng):
    """y (0..1 from the top) of the silhouette for every x."""
    x = np.arange(W) / W
    if kind == 'fire':
        n = np.cumsum(rng.normal(0, 1, W))
        n = (n - n.min()) / (np.ptp(n) + 1e-6)
        spikes = np.abs(((x * 9.0) % 1.0) - 0.5) * 2
        return 0.66 - 0.2 * spikes * (0.5 + n * 0.8) - 0.04 * n
    if kind == 'water':
        return 0.84 - 0.04 * np.sin(x * 19 + 1) - 0.025 * np.sin(x * 41) - 0.03 * np.sin(x * 7)
    n = np.convolve(rng.normal(0, 1, W + 40), np.ones(41) / 41, 'valid')[:W]
    n = (n - n.min()) / (np.ptp(n) + 1e-6)
    return 0.78 - 0.26 * n - 0.05 * np.abs(np.sin(x * 13))


def tile(name, path, out):
    rng = np.random.default_rng(1000 + sorted(SRC).index(name))
    st = STYLE[name]
    im = Image.open(path).convert('RGB')
    w, h = im.size
    nh = min(h, int(w * 9 / 16))
    top = (h - nh) // 2
    im = im.crop((0, top, w, top + nh)).resize((W, H), Image.LANCZOS)
    a = np.asarray(im).astype(np.float32)
    y = a @ np.array([0.3, 0.59, 0.11], np.float32)
    a = y[..., None] + (a - y[..., None]) * st['keep']
    a *= 0.62
    yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
    g = np.exp(-(((yy / H) - 0.62) ** 2) / 0.03)[..., None] * np.array(st['glow'], np.float32) / 255.0
    a = a + g * 70
    if name in ('fire', 'water', 'earth'):
        r = ridge(name, rng)
        mask = (yy / H) > np.tile(r[None, :], (H, 1))
        a[mask] = a[mask] * 0.12 + np.array(st['ridge'], np.float32) * 0.9
    elif name == 'air':
        m = Image.new('L', (W, H), 0)
        d = ImageDraw.Draw(m)
        for cx, cy, rw in ((90, 205, 70), (270, 232, 110), (400, 190, 54)):
            d.ellipse((cx - rw, cy - 9, cx + rw, cy + 9), fill=255)
            d.polygon([(cx - rw * 0.7, cy + 4), (cx + rw * 0.7, cy + 4), (cx + rw * 0.2, cy + 30), (cx - rw * 0.3, cy + 22)], fill=255)
        mm = np.asarray(m.filter(ImageFilter.GaussianBlur(1.2))).astype(np.float32)[..., None] / 255.0
        a = a * (1 - mm) + np.array(st['ridge'], np.float32) * mm
    else:
        m = Image.new('L', (W, H), 0)
        d = ImageDraw.Draw(m)
        for i in range(7):
            s = i * 51 + 8
            d.arc((130, 50, 350, 250), s, s + 34, fill=255, width=7)
        mm = np.asarray(m.filter(ImageFilter.GaussianBlur(1.6))).astype(np.float32)[..., None] / 255.0
        a = a * (1 - mm * 0.8) + np.array(st['glow'], np.float32) * mm * 0.35
    v = 1 - 0.75 * (((xx / W - 0.5) * 2) ** 2 * 0.55 + ((yy / H - 0.5) * 2) ** 2 * 0.8)
    a *= np.clip(v, 0.18, 1)[..., None]
    a += rng.normal(0, 4.5, (H, W, 1))
    Image.fromarray(np.clip(a, 0, 255).astype(np.uint8)).save(out, 'WEBP', quality=70, method=6)


if __name__ == '__main__':
    dest = sys.argv[1]
    root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..', 'public', 'assets', 'img')
    for n, p in SRC.items():
        tile(n, os.path.join(root, p), os.path.join(dest, n + '.webp'))
